"""Starting helper processes with a handover of the caller's objects.

Windows decides what a child may reach at process-creation time.  Simply
enabling inheritance (``bInheritHandles=TRUE``) hands over *every* inheritable
handle in the parent, which is exactly what the sandbox must not do, and
disabling it hands over nothing.  The middle setting is
``PROC_THREAD_ATTRIBUTE_HANDLE_LIST``: the child receives the listed handles and
nothing else, and each listed handle keeps the same numeric value it had in the
parent.
"""

import os
import subprocess

from . import _winapi
from .errors import WSpawnError
from .inherit import _as_number, _translate
from .kinds import handle_kind

_STD_STREAMS = ("stdin", "stdout", "stderr")


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, popen, inherit):
        self._popen = popen
        self.inherit = tuple(inherit)
        self.pid = popen.pid
        self.returncode = None
        # Present when the caller asked for a pipe on that stream.
        self.stdin = popen.stdin
        self.stdout = popen.stdout
        self.stderr = popen.stderr

    def wait(self, timeout=None):
        self.returncode = self._popen.wait(timeout=timeout)
        return self.returncode

    def poll(self):
        self.returncode = self._popen.poll()
        return self.returncode

    def communicate(self, input=None, timeout=None):
        out = self._popen.communicate(input=input, timeout=timeout)
        self.returncode = self._popen.returncode
        return out

    def terminate(self):
        self._popen.terminate()

    def kill(self):
        self._popen.kill()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError("argv must be a sequence of arguments, not a single string", kind="badarg")
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError("argv must be an iterable of paths: %s" % exc, kind="badarg") from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    try:
        items = list(inherit)
    except TypeError as exc:
        raise WSpawnError("inherit must be a sequence of handles: %s" % exc, kind="badarg") from exc

    handles = []
    for item in items:
        if isinstance(item, bool) or not isinstance(item, int):
            raise WSpawnError(
                "inherit must contain integer handles, got %r" % (item,), kind="badarg")
        number = _as_number(item)
        if number == 0:
            raise WSpawnError("not a usable object handle: 0", kind="badarg", handle=item)
        if number not in handles:
            handles.append(number)
    return tuple(handles)


def _check_transferable(handles):
    """Reject handles that cannot be handed over before touching any flags."""
    for handle in handles:
        try:
            _winapi.handle_flags(handle)
        except OSError as exc:
            raise _translate(exc, handle) from exc
        # Console handles with their low two bits set are not real kernel
        # objects; CreateProcess rejects them in a handle list.
        if handle & 0x3 == 0x3 and handle_kind(handle) in ("console", "unknown"):
            raise WSpawnError(
                "console pseudo handles cannot be handed over explicitly",
                kind="unsupported", handle=handle)


def _make_inheritable(handles):
    """Turn the inherit flag on, returning the handles that had to be changed."""
    changed = []
    try:
        for handle in handles:
            try:
                flags = _winapi.handle_flags(handle)
            except OSError as exc:
                raise _translate(exc, handle) from exc
            if flags & _winapi.HANDLE_FLAG_INHERIT:
                continue
            try:
                _winapi.set_handle_flags(
                    handle, _winapi.HANDLE_FLAG_INHERIT, _winapi.HANDLE_FLAG_INHERIT)
            except OSError as exc:
                raise _translate(exc, handle) from exc
            changed.append(handle)
    except BaseException:
        _restore(changed)
        raise
    return changed


def _restore(handles):
    """Put the inherit flag back for handles :func:`_make_inheritable` changed."""
    for handle in handles:
        try:
            _winapi.set_handle_flags(handle, _winapi.HANDLE_FLAG_INHERIT, 0)
        except OSError:
            pass


def _startupinfo(handles, startupinfo):
    """Return a STARTUPINFO carrying the explicit handle list."""
    info = startupinfo
    if info is None:
        info = subprocess.STARTUPINFO()
    elif not isinstance(info, subprocess.STARTUPINFO):
        raise WSpawnError(
            "startupinfo must be a subprocess.STARTUPINFO, got %r" % (startupinfo,),
            kind="badarg")

    attributes = dict(info.lpAttributeList or {})
    listed = list(attributes.get("handle_list") or [])
    for handle in handles:
        if handle not in listed:
            listed.append(handle)
    attributes["handle_list"] = listed
    info.lpAttributeList = attributes
    return info


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None, **kwargs):
    """Start a helper process, handing it the objects named in ``inherit``.

    The helper can reach the objects in ``inherit`` plus whichever standard
    streams the caller passes explicitly, and nothing else: other inheritable
    objects in this process stay out of reach.  Each handed-over object keeps
    its numeric handle value inside the helper.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    for name in _STD_STREAMS:
        kwargs.pop(name, None)
    startupinfo = kwargs.pop("startupinfo", None)

    if not _winapi.is_windows():
        raise WSpawnError(
            "an explicit handle handover requires Windows", kind="unsupported")

    _check_transferable(handles)
    info = _startupinfo(handles, startupinfo)
    changed = _make_inheritable(handles)
    try:
        popen = subprocess.Popen(
            command,
            # close_fds keeps Popen from widening inheritance on its own: the
            # handle list is the only thing that crosses the boundary, and the
            # standard streams Popen is told about are added to it.
            close_fds=True,
            stdin=stdin,
            stdout=stdout,
            stderr=stderr,
            startupinfo=info,
            **kwargs
        )
    except OSError as exc:
        code = getattr(exc, "winerror", None)
        kind = _winapi.error_kind(code) if code else "os"
        raise WSpawnError(str(exc), kind=kind) from exc
    except (TypeError, ValueError) as exc:
        raise WSpawnError(str(exc), kind="badarg") from exc
    finally:
        # Leave the caller's own flags exactly as they were; only the ones this
        # call switched on are switched back off.
        _restore(changed)
    return SpawnedProcess(popen, handles)
